/** One hosted v2 deployment record and log client for CLI tests. */
export function hostedSessionFixture(teamId, slug = "danny") {
    return {
        deployment: {
            applicationId: `app_${slug}`,
            releaseId: `rel_${slug}_1`,
            slug,
            teamId,
            status: "running",
            progress: "running",
            statusMessage: null,
        },
        logClient(args) {
            return {
                async getAgentkitDeploymentLogs() {
                    return [{ sessionId: "ses_new", lines: args.lines ?? ["turn started"] }];
                },
                async getAgentkitPersistentStageLogs() {
                    return { files: [], selected: null, lines: args.stageLines ?? ["listening on :3000"] };
                },
                async getAgentkitSessionRuns() {
                    return {
                        executions: [],
                        startLog: args.startLog === undefined ? "boot\n" : args.startLog,
                    };
                },
                getAgentkitSessionEvents(eventArgs) {
                    return args.events(eventArgs.afterEventIndex);
                },
                // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- the fixture implements only the log methods these tests call
            };
        },
    };
}
